<?php
declare(strict_types=1);
function at_metric_cards(array $metrics,string $variant='classic',int $limit=12): void {$metrics=array_slice($metrics,0,$limit);echo '<div class="at-metrics at-'.$variant.'">';foreach($metrics as $m){$href=trim((string)($m['href']??''));echo '<article class="at-metric '.e($m['accent']??'blue').'">';if($href!=='')echo '<a class="at-stretch" href="'.e($href).'"></a>';echo '<div class="at-metric-top"><span>'.e($m['label']).'</span><i>'.e($m['icon']).'</i></div><strong>'.e($m['value']).'</strong><small>'.e($m['note']).'</small></article>';}echo '</div>';}
function at_growth_chart(array $months,string $variant='bars'): void {$max=1;foreach($months as $m)$max=max($max,(int)$m['users'],(int)$m['businesses']);echo '<div class="at-chart at-chart-'.$variant.'">';foreach($months as $m){$u=max(4,(int)round(((int)$m['users']/$max)*180));$b=max(4,(int)round(((int)$m['businesses']/$max)*180));echo '<div class="at-chart-col"><div class="at-chart-bars"><i class="users" style="height:'.$u.'px"></i><i class="biz" style="height:'.$b.'px"></i></div><b>'.e($m['label']).'</b><small>'.e($m['users']).'/'.e($m['businesses']).'</small></div>';}echo '</div>';}
function at_quick_actions(array $actions,string $variant='cards'): void {echo '<div class="at-quick at-'.$variant.'">';foreach($actions as $a)echo '<a href="'.e($a['href']).'"><i>'.e($a['icon']).'</i><div><strong>'.e($a['title']).'</strong><span>'.e($a['desc']).'</span></div></a>';echo '</div>';}
function at_activity(array $feed): void {echo '<div class="at-activity">';if(!$feed){echo '<div class="empty-state">No recent activity yet.</div>';return;}foreach($feed as $x)echo '<div class="at-activity-row"><i>'.e($x['icon']).'</i><div><strong>'.e($x['title']).'</strong><span>'.e($x['meta']).'</span></div><time>'.e($x['time']).'</time></div>';echo '</div>';}
function at_health(array $health,string $variant='meters'): void {echo '<div class="at-health at-health-'.$variant.'">';foreach($health as $h){$pct=max(0,min(100,(int)$h['pct']));echo '<div class="at-health-item"><div><strong>'.e($h['label']).'</strong><span>'.e($h['note']).'</span></div><b>'.$pct.'%</b><div class="at-health-track"><i style="width:'.$pct.'%"></i></div></div>';}echo '</div>';}
function at_recent_table(string $title,array $headers,array $rows,string $href=''): void {echo '<section class="at-panel"><div class="at-panel-head"><div><h3>'.e($title).'</h3><span>Live database records</span></div>';if($href!=='')echo '<a href="'.e($href).'">Manage ↗</a>';echo '</div><div class="at-table"><table><tr>';foreach($headers as $h)echo '<th>'.e($h).'</th>';echo '</tr>';if(!$rows)echo '<tr><td colspan="'.count($headers).'">No records available.</td></tr>';foreach($rows as $row){echo '<tr>';foreach($row as $cell)echo '<td>'.$cell.'</td>';echo '</tr>';}echo '</table></div></section>';}
function at_custom_widgets(array $widgets): void {if(!$widgets)return;echo '<div class="at-custom-widget-grid">';foreach($widgets as $w){$type=$w['widget_type'];$source=(string)($w['metric_source']??'');$val=in_array($type,['metric','progress'],true)?dashboard_metric_value($source):0;$display=in_array($type,['metric','progress'],true)?dashboard_metric_display($source,$val):'';echo '<article class="at-custom-widget '.e($w['accent']??'blue').'">';if($w['target_url'])echo '<a class="at-stretch" href="'.e($w['target_url']).'"></a>';echo '<div><span>'.e($w['title']).'</span><i>'.e($w['icon']?:'◆').'</i></div>';if($type==='metric'||$type==='progress')echo '<strong>'.e($display).'</strong>';elseif($type==='quick_link')echo '<strong>Open ↗</strong>';else echo '<strong>Info</strong>';echo '<small>'.e($w['note_text']?:($source?:'Custom dashboard widget')).'</small></article>';}echo '</div>';}
